  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine showed very low mean oral systemic availability of 4.9% in patients, directly below the 20% threshold, and has the highest assay-transfer score among the evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Felodipine absolute bioavailability in humans was 15%, below the 20% threshold, providing strong transferable evidence for low oral bioavailability.",
