    {
      "card_ids": ["C37"],
      "claim": "Tegaserod absolute bioavailability was approximately 10% in healthy volunteers, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain ester prodrug with structural parallels to the query's ester/lactone lipophilicity, had absolute oral bioavailability of 6.83% in young women.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat showed poor oral bioavailability in humans, supporting low systemic availability for a complex lipophilic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Nitrendipine absolute bioavailability was 10.7% in humans after oral tablet administration, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to low oral bioavailability: every retrieved analogue with relevant human bioavailability data falls below the 20% threshold, and the query's highly lipophilic ester/lactone structure is consistent with minimal systemic absorption. No contradictory high-bioavailability evidence was identified.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself was provided; the prediction relies on transferable analogues.",
    "Some analogues are structurally distant (e.g., colesevelam, delmopinol) and were not weighted heavily.",
    "The query's known profile as a minimally absorbed GI-targeted lipase inhibitor is not explicitly represented in the supplied evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

